# Adaptive Rejection Sampling (Gilks & Wild, 1992)
#
# The log-density h(x) = log f(x) of a (possibly unnormalised) density must be
# concave.  A piecewise-linear upper hull made of tangents to h is used as an
# envelope, and the hull is refined with rejected points.  Samples from the
# envelope are accepted with probability f(y) / exp(upper_hull(y)).

## ---------------------------------------------------------------------------
## Small numerical helpers
## ---------------------------------------------------------------------------

.log_sum_exp <- function(x) {
  m <- max(x)
  if (!is.finite(m)) return(m)
  m + log(sum(exp(x - m)))
}

# log(exp(a) - exp(b)) for a >= b
.log_diff_exp <- function(a, b) {
  if (b == -Inf) return(a)
  if (a < b) return(-Inf)
  if (a == b) return(-Inf)
  a + log1p(-exp(b - a))
}

# log of integral from lo to hi of exp(a + s*x) dx
.log_segment_integral <- function(a, s, lo, hi) {
  if (is.infinite(lo) && is.infinite(hi))
    stop("Density has an infinite domain on both sides; not supported.")

  if (abs(s) < 1e-12) {
    if (!is.finite(lo) || !is.finite(hi))
      stop("Non-integrable constant envelope on an unbounded interval.")
    if (hi <= lo) return(-Inf)
    return(a + log(hi - lo))
  }

  if (is.finite(lo) && is.finite(hi)) {
    if (hi <= lo) return(-Inf)
    l_lo <- a + s * lo
    l_hi <- a + s * hi
    if (s > 0) {
      .log_diff_exp(l_hi, l_lo) - log(s)
    } else {
      .log_diff_exp(l_lo, l_hi) - log(-s)
    }
  } else if (!is.finite(lo)) {
    # (-Inf, hi]: require s > 0 for integrability
    if (s <= 0) return(Inf) # signals an invalid (non-integrable) envelope
    a + s * hi - log(s)
  } else {
    # [lo, Inf): require s < 0
    if (s >= 0) return(Inf)
    a + s * lo - log(-s)
  }
}

## ---------------------------------------------------------------------------
## Density / derivative evaluation
## ---------------------------------------------------------------------------

# Evaluate the unnormalised density in a vectorised way and return log f.
.eval_log_density <- function(f, x, context = "density") {
  val <- tryCatch(f(x), error = function(e)
    stop(sprintf("The density function failed for %s: %s", context,
                 conditionMessage(e))))
  val <- as.numeric(val)
  if (length(val) != length(x))
    stop(sprintf(paste0("The density function is not vectorised: for %d input ",
                        "values it returned %d value(s)."),
                 length(x), length(val)))
  if (any(!is.na(val) & val < 0))
    stop("The density function returned negative values.")
  ifelse(is.na(val) | val <= 0, -Inf, log(val))
}

# Numerical derivative of h.  Central differences are used in the interior and
# one-sided differences at finite boundaries.
.derivative_h <- function(f, x, lower, upper) {
  eps <- 1e-6 * pmax(1, abs(x))
  h0 <- .eval_log_density(f, x, "derivative evaluation")
  h_l <- .eval_log_density(f, x - eps, "derivative evaluation")
  h_r <- .eval_log_density(f, x + eps, "derivative evaluation")

  in_left  <- (x - eps) > lower
  in_right <- (x + eps) < upper

  central <- in_left & in_right & is.finite(h_l) & is.finite(h_r)
  right   <- !central & in_right & is.finite(h_r)
  left    <- !central & !right & in_left & is.finite(h_l)

  s <- rep(NA_real_, length(x))
  s[central] <- (h_r[central] - h_l[central]) / (2 * eps[central])
  s[right]   <- (h_r[right] - h0[right]) / eps[right]
  s[left]    <- (h0[left] - h_l[left]) / eps[left]
  s[!is.finite(s)] <- NA_real_
  s
}

## ---------------------------------------------------------------------------
## Initial abscissae and hull construction
## ---------------------------------------------------------------------------

# Choose initial abscissae, then expand the outermost points when a tail of an
# unbounded domain would not have an integrable tangent.
.initial_abscissae <- function(f, lower, upper, max_points) {
  if (is.finite(lower) && is.finite(upper)) {
    centre <- (lower + upper) / 2
    step <- (upper - lower) / 4
  } else if (is.finite(lower)) {
    centre <- lower + 1
    step <- 1
  } else if (is.finite(upper)) {
    centre <- upper - 1
    step <- 1
  } else {
    centre <- 0
    step <- 1
  }

  candidates <- centre + c(-2, -1, 0, 1, 2) * step
  candidates <- candidates[candidates >= lower & candidates <= upper]
  candidates <- sort(unique(candidates))
  hc <- .eval_log_density(f, candidates, "initial abscissae")
  xs <- candidates[is.finite(hc)]

  # Fallback grid if the first guess missed the support.
  if (length(xs) < 2L) {
    grid <- if (is.finite(lower) && is.finite(upper)) {
      seq(lower, upper, length.out = 11)
    } else if (is.finite(lower)) {
      lower + c(0, 1, 2, 4, 8, 16)
    } else if (is.finite(upper)) {
      upper - c(0, 1, 2, 4, 8, 16)
    } else {
      c(-16, -8, -4, -2, -1, 0, 1, 2, 4, 8, 16)
    }
    grid <- sort(unique(grid[grid >= lower & grid <= upper]))
    hg <- .eval_log_density(f, grid, "initial abscissae")
    xs <- grid[is.finite(hg)]
  }
  if (length(xs) < 2L)
    stop("Could not find at least two points with positive finite density.")

  # Expand an unbounded left tail until its leftmost slope is positive.
  expand_step <- step
  for (i in seq_len(60L)) {
    if (is.finite(lower) || length(xs) >= max_points) break
    s <- .derivative_h(f, xs[1], lower, upper)
    if (is.finite(s) && s > 1e-10) break
    expand_step <- expand_step * 2
    new_x <- xs[1] - expand_step
    h_new <- .eval_log_density(f, new_x, "left-tail expansion")
    if (!is.finite(h_new))
      stop("Could not construct an integrable envelope in the left tail; ",
           "the density may not be log-concave or may have bounded support.")
    xs <- c(new_x, xs)
  }

  # Expand an unbounded right tail until its rightmost slope is negative.
  expand_step <- step
  for (i in seq_len(60L)) {
    if (is.finite(upper) || length(xs) >= max_points) break
    s <- .derivative_h(f, xs[length(xs)], lower, upper)
    if (is.finite(s) && s < -1e-10) break
    expand_step <- expand_step * 2
    new_x <- xs[length(xs)] + expand_step
    h_new <- .eval_log_density(f, new_x, "right-tail expansion")
    if (!is.finite(h_new))
      stop("Could not construct an integrable envelope in the right tail; ",
           "the density may not be log-concave or may have bounded support.")
    xs <- c(xs, new_x)
  }

  if (!is.finite(lower)) {
    s_left <- .derivative_h(f, xs[1], lower, upper)
    if (!is.finite(s_left) || s_left <= 1e-10)
      stop("The left tail is not integrable; the density is not log-concave ",
           "or is not normalisable.")
  }
  if (!is.finite(upper)) {
    s_right <- .derivative_h(f, xs[length(xs)], lower, upper)
    if (!is.finite(s_right) || s_right >= -1e-10)
      stop("The right tail is not integrable; the density is not log-concave ",
           "or is not normalisable.")
  }

  sort(unique(xs))
}

# Build the piecewise-linear upper hull from abscissae x, h and slopes s.
.build_hull <- function(x, h, s, lower, upper) {
  ord <- order(x)
  x <- x[ord]; h <- h[ord]; s <- s[ord]
  k <- length(x)
  if (k < 2L) stop("At least two abscissae are needed to build the hull.")

  slope_scale <- max(1, max(abs(s), na.rm = TRUE))
  slope_tol <- 1e-4 * slope_scale
  if (any(!is.finite(s))) stop("Could not compute finite log-density slopes.")
  if (any(diff(s) > slope_tol)) {
    stop("Non-log-concave density detected: the slopes of the log-density ",
         "are not non-increasing at the abscissae (the density may be ",
         "multimodal or log-convex).")
  }

  # Intersections of neighbouring tangents.
  if (k > 2L) {
    z <- numeric(k - 1L)
    for (i in seq_len(k - 1L)) {
      d <- s[i] - s[i + 1L]
      if (d > slope_tol) {
        z[i] <- (h[i + 1L] - h[i] + s[i] * x[i] -
                   s[i + 1L] * x[i + 1L]) / d
      } else {
        # (Nearly) equal slopes: tangents coincide (e.g. exponential density).
        z[i] <- (x[i] + x[i + 1L]) / 2
      }
    }
    z <- pmax(z, lower)
    z <- pmin(z, upper)
    z <- cummax(z)
    breaks <- c(lower, z, upper)
  } else {
    breaks <- c(lower, upper)
  }
  breaks <- pmax(breaks, lower)
  breaks <- pmin(breaks, upper)
  breaks <- cummax(breaks)

  a <- h - s * x
  logI <- vapply(seq_len(k), function(j) {
    .log_segment_integral(a[j], s[j], breaks[j], breaks[j + 1L])
  }, numeric(1))

  if (any(is.infinite(logI) & logI > 0))
    stop("Non-integrable envelope; the density may not be log-concave.")

  list(x = x, h = h, s = s, a = a, breaks = breaks,
       logI = logI, lower = lower, upper = upper)
}

## ---------------------------------------------------------------------------
## Envelope sampling and acceptance
## ---------------------------------------------------------------------------

# Draw one value from the piecewise exponential upper hull.
.sample_envelope <- function(hull) {
  logI <- hull$logI
  if (all(!is.finite(logI)))
    stop("The envelope has zero mass; the density may be invalid.")
  j <- sample.int(length(logI), size = 1L,
                  prob = exp(logI - max(logI)))
  lo <- hull$breaks[j]; hi <- hull$breaks[j + 1L]
  a <- hull$a[j]; s <- hull$s[j]
  u <- runif(1)

  if (is.finite(lo) && is.finite(hi)) {
    if (abs(s) < 1e-12) return(lo + u * (hi - lo))
    l0 <- a + s * lo; l1 <- a + s * hi
    m <- max(l0, l1)
    q <- m + log(exp(l0 - m) + u * (exp(l1 - m) - exp(l0 - m)))
    (q - a) / s
  } else if (!is.finite(lo)) {
    hi + log(u) / s          # s > 0 for an integrable left tail
  } else {
    lo + log(u) / s          # s < 0 for an integrable right tail
  }
}

.env_log_density <- function(hull, y) {
  j <- findInterval(y, hull$breaks, rightmost.closed = TRUE)
  j <- min(max(j, 1L), length(hull$s))
  hull$a[j] + hull$s[j] * y
}

# Check concavity locally using the derivative at the proposed point.
.check_log_concavity <- function(hull, y, s_y) {
  x <- hull$x
  s <- hull$s
  scale <- max(1, abs(s_y), max(abs(s)))
  tol <- 1e-4 * scale

  if (y < x[1]) {
    ok <- s_y >= s[1] - tol
  } else if (y > x[length(x)]) {
    ok <- s_y <= s[length(s)] + tol
  } else {
    i <- findInterval(y, x)
    i <- min(max(i, 1L), length(x) - 1L)
    ok <- s[i] + tol >= s_y && s_y >= s[i + 1L] - tol
  }
  if (!isTRUE(ok))
    stop("Non-log-concave density detected: the log-density slope is not ",
         "non-increasing at a proposed point.")
  invisible(TRUE)
}

## ---------------------------------------------------------------------------
## Main function
## ---------------------------------------------------------------------------

#' Adaptive rejection sampler
#'
#' @param f vectorised function returning the (possibly unnormalised) density,
#'   or a character expression in x, e.g. "exp(-x^2/2)" or "dnorm(x)".
#' @param n positive integer number of samples.
#' @param lower,upper finite or infinite domain bounds.
#' @param max_points maximum number of hull abscissae kept (>= 3).
#' @param max_iter maximum envelope proposals per requested sample.
#' @return numeric vector of length n with attributes acceptance_rate and
#'   n_abscissae.
ars <- function(f, n, lower = -Inf, upper = Inf,
                max_points = 100L, max_iter = 100000L) {
  # ---- input validation ---------------------------------------------------
  if (missing(f)) stop("Argument 'f' (the density) is required.")
  if (is.character(f) && length(f) == 1L) {
    f <- tryCatch(
      eval(parse(text = paste0("function(x) ", f)), envir = parent.frame()),
      error = function(e) stop("Could not parse the density expression: ",
                               conditionMessage(e)))
  }
  if (!is.function(f))
    stop("'f' must be a function or a character expression in x.")

  if (length(n) != 1L || !is.numeric(n) || is.na(n) || !is.finite(n) ||
      n <= 0 || n != floor(n))
    stop("'n' must be a single positive integer.")
  n <- as.integer(n)

  if (length(lower) != 1L || length(upper) != 1L ||
      !is.numeric(lower) || !is.numeric(upper) ||
      is.na(lower) || is.na(upper))
    stop("'lower' and 'upper' must be single numeric values.")
  if (lower >= upper)
    stop("Invalid domain: 'lower' must be strictly less than 'upper'.")
  if (lower == Inf || upper == -Inf)
    stop("Invalid domain: bounds must not be +Inf for 'lower' or -Inf for 'upper'.")

  if (length(max_points) != 1L || !is.finite(max_points) ||
      max_points < 3L || max_points != floor(max_points))
    stop("'max_points' must be an integer >= 3.")
  max_points <- as.integer(max_points)

  # Vectorisation check at two distinct points.
  probe <- c(if (is.finite(lower)) lower + 0.25 else -0.5,
             if (is.finite(upper)) upper - 0.25 else 0.5)
  probe <- unique(pmax(pmin(probe, upper), lower))
  if (length(probe) == 1L) probe <- c(probe, probe + min(1, (upper - lower) / 2))
  invisible(.eval_log_density(f, probe, "vectorisation check"))

  # ---- initial hull -------------------------------------------------------
  xs <- .initial_abscissae(f, lower, upper, max_points)
  hs <- .eval_log_density(f, xs, "initial hull")
  ss <- .derivative_h(f, xs, lower, upper)
  if (any(!is.finite(ss)))
    stop("Could not compute the log-density derivative at the initial points.")
  hull <- .build_hull(xs, hs, ss, lower, upper)

  # ---- adaptive rejection sampling ---------------------------------------
  samples <- numeric(n)
  n_done <- 0L
  attempts <- 0L
  while (n_done < n) {
    if (attempts >= max_iter)
      stop("Maximum number of proposals reached (acceptance rate too low).")
    attempts <- attempts + 1L

    y <- .sample_envelope(hull)
    if (!is.finite(y) || y < lower || y > upper) next
    h_y <- .eval_log_density(f, y, "proposal")
    if (!is.finite(h_y)) next             # outside support: reject

    # Check log-concavity and that the tangent hull really is an upper bound.
    s_y <- .derivative_h(f, y, lower, upper)
    if (!is.finite(s_y)) next
    env_y <- .env_log_density(hull, y)
    if (h_y > env_y + 1e-5 * max(1, abs(h_y))) {
      stop("Non-log-concave density detected: the log-density lies above ",
           "the tangent upper hull at a proposed point.")
    }
    .check_log_concavity(hull, y, s_y)

    if (log(runif(1)) <= h_y - env_y) {
      n_done <- n_done + 1L
      samples[n_done] <- y
    } else if (length(hull$x) < max_points) {
      # Refine the hull with the rejected point.
      xs_new <- sort(unique(c(hull$x, y)))
      hs_new <- .eval_log_density(f, xs_new, "hull refinement")
      ss_new <- .derivative_h(f, xs_new, lower, upper)
      if (all(is.finite(ss_new))) {
        hull <- tryCatch(.build_hull(xs_new, hs_new, ss_new, lower, upper),
                         error = function(e) {
                           stop(conditionMessage(e), call. = FALSE)
                         })
      }
    }
  }

  attr(samples, "acceptance_rate") <- n / attempts
  attr(samples, "n_abscissae") <- length(hull$x)
  samples
}

## ---------------------------------------------------------------------------
## Formal tests
## ---------------------------------------------------------------------------

.report <- function(name, pass, mean = NA_real_, sd = NA_real_,
                    expected_mean = NA_real_, expected_sd = NA_real_,
                    detail = "") {
  status <- if (isTRUE(pass)) "PASS" else "FAIL"
  cat(sprintf(paste0("%s: %s | sample mean=%.4f, sample sd=%.4f, ",
                     "expected mean=%.4f, expected sd=%.4f%s\n"),
              name, status, mean, sd, expected_mean, expected_sd,
              if (nzchar(detail)) paste0(" | ", detail) else ""))
  isTRUE(pass)
}

.moment_test <- function(x, expected_mean, expected_sd, nsig = 5) {
  n <- length(x)
  observed_mean <- mean(x)
  observed_sd <- sd(x)
  mean_ok <- abs(observed_mean - expected_mean) <
    nsig * expected_sd / sqrt(n)
  sd_ok <- abs(observed_sd - expected_sd) <
    max(0.1 * expected_sd, nsig * expected_sd / sqrt(2 * n))
  list(pass = mean_ok && sd_ok, mean = observed_mean, sd = observed_sd)
}

#' Run the formal test suite
#'
#' Prints one TEST_NAME: PASS / TEST_NAME: FAIL line per test together with
#' sample mean and standard deviation, and writes sample files.
#' @return invisibly a data.frame of test results.
test <- function(n = 5000L, seed = 2024L) {
  cat("=== Adaptive Rejection Sampler Test Suite ===\n")
  cat(sprintf("Samples per distribution: %d, random seed: %d\n\n", n, seed))
  set.seed(seed)
  results <- list()

  add <- function(name, pass, ...) {
    results[[name]] <<- isTRUE(pass)
    .report(name, pass, ...)
  }

  # ---- Normal(0, 1) -------------------------------------------------------
  cat("[1/8] Sampling Normal(0,1) ...\n")
  normal_samples <- tryCatch(
    ars(dnorm, n, lower = -Inf, upper = Inf),
    error = function(e) {
      cat("  ERROR:", conditionMessage(e), "\n")
      NULL
    })
  if (is.null(normal_samples)) {
    add("TEST_NORMAL_MEAN", FALSE, detail = "sampling failed")
    add("TEST_NORMAL_SD", FALSE, detail = "sampling failed")
    add("TEST_NORMAL_KS", FALSE, detail = "sampling failed")
  } else {
    m <- .moment_test(normal_samples, 0, 1)
    add("TEST_NORMAL_MEAN", m$pass, m$mean, m$sd, 0, 1,
        sprintf("acceptance=%.2f", attr(normal_samples, "acceptance_rate")))
    add("TEST_NORMAL_SD",
        abs(m$sd - 1) < max(0.1, 5 / sqrt(2 * n)),
        m$mean, m$sd, 0, 1)
    ks <- suppressWarnings(ks.test(normal_samples, pnorm))
    add("TEST_NORMAL_KS", ks$p.value > 0.01, m$mean, m$sd, 0, 1,
        sprintf("KS p-value=%.4f (need > 0.01)", ks$p.value))
  }

  # ---- Exponential(rate = 2) ---------------------------------------------
  cat("[2/8] Sampling Exponential(rate=2) ...\n")
  exp_samples <- tryCatch(
    ars(function(x) dexp(x, rate = 2), n, lower = 0, upper = Inf),
    error = function(e) {
      cat("  ERROR:", conditionMessage(e), "\n")
      NULL
    })
  if (is.null(exp_samples)) {
    add("TEST_EXPONENTIAL_MEAN", FALSE, detail = "sampling failed")
    add("TEST_EXPONENTIAL_SD", FALSE, detail = "sampling failed")
    add("TEST_EXPONENTIAL_KS", FALSE, detail = "sampling failed")
  } else {
    m <- .moment_test(exp_samples, 0.5, 0.5)
    add("TEST_EXPONENTIAL_MEAN", m$pass, m$mean, m$sd, 0.5, 0.5,
        sprintf("acceptance=%.2f", attr(exp_samples, "acceptance_rate")))
    add("TEST_EXPONENTIAL_SD",
        abs(m$sd - 0.5) < max(0.05, 5 * 0.5 / sqrt(2 * n)),
        m$mean, m$sd, 0.5, 0.5)
    ks <- suppressWarnings(ks.test(exp_samples, pexp, rate = 2))
    add("TEST_EXPONENTIAL_KS", ks$p.value > 0.01, m$mean, m$sd, 0.5, 0.5,
        sprintf("KS p-value=%.4f (need > 0.01)", ks$p.value))
  }

  # ---- Expression interface ----------------------------------------------
  cat("[3/8] Sampling from a character expression ...\n")
  expr_samples <- tryCatch(
    ars("dnorm(x, mean = 0, sd = 1)", n, lower = -Inf, upper = Inf),
    error = function(e) {
      cat("  ERROR:", conditionMessage(e), "\n")
      NULL
    })
  if (is.null(expr_samples)) {
    add("TEST_EXPRESSION_INPUT", FALSE, detail = "sampling failed")
  } else {
    m <- .moment_test(expr_samples, 0, 1)
    add("TEST_EXPRESSION_INPUT", m$pass, m$mean, m$sd, 0, 1)
  }

  # ---- Independence of consecutive draws ---------------------------------
  cat("[4/8] Checking serial independence of samples ...\n")
  if (is.null(normal_samples)) {
    add("TEST_INDEPENDENCE", FALSE, detail = "sampling failed")
  } else {
    rho <- cor(normal_samples[-length(normal_samples)],
               normal_samples[-1])
    add("TEST_INDEPENDENCE", abs(rho) < 0.1,
        mean(normal_samples), sd(normal_samples), 0, 1,
        sprintf("lag-1 autocorrelation=%.4f (need |rho| < 0.1)", rho))
  }

  # ---- Input validation ---------------------------------------------------
  cat("[5/8] Checking rejection of invalid inputs ...\n")
  raises_error <- function(expr) {
    tryCatch({ force(expr); FALSE }, error = function(e) TRUE)
  }
  invalid_ok <- all(
    raises_error(ars(dnorm, n = -5)),
    raises_error(ars(dnorm, n = 0)),
    raises_error(ars(dnorm, n = 2.5)),
    raises_error(ars(dnorm, n = 10, lower = 2, upper = 1)),
    raises_error(ars(dnorm, n = 10, lower = NA, upper = 1)),
    raises_error(ars("not valid R (", n = 10)),
    raises_error(ars(42, n = 10))
  )
  add("TEST_INVALID_INPUTS", invalid_ok, detail =
        "negative/zero/non-integer n, bad domain, NA, bad expression, non-function")

  # ---- Non-log-concave detection ----------------------------------------
  cat("[6/8] Checking detection of a non-log-concave density ...\n")
  nc_message <- tryCatch({
    ars(function(x) exp(x^2 / 2), n = 100, lower = -1, upper = 1)
    ""
  }, error = function(e) conditionMessage(e))
  nc_ok <- grepl("log-concave", nc_message, ignore.case = TRUE)
  add("TEST_NON_LOG_CONCAVE", nc_ok, detail =
        if (nc_ok) "non-log-concave density correctly rejected"
        else paste0("unexpected outcome: ", nc_message))

  # ---- Truncated normal on (0, 2) ---------------------------------------
  cat("[7/8] Sampling truncated Normal(0,1) on (0,2) ...\n")
  trunc_samples <- tryCatch(
    ars(dnorm, n, lower = 0, upper = 2),
    error = function(e) {
      cat("  ERROR:", conditionMessage(e), "\n")
      NULL
    })
  if (is.null(trunc_samples)) {
    add("TEST_TRUNCATED_NORMAL", FALSE, detail = "sampling failed")
  } else {
    # Known moments of the standard normal truncated to (0, 2).
    alpha <- 0; beta <- 2
    Z <- pnorm(beta) - pnorm(alpha)
    phi <- function(x) dnorm(x)
    true_mean <- (phi(alpha) - phi(beta)) / Z
    true_sd <- sqrt(1 + (alpha * phi(alpha) - beta * phi(beta)) / Z -
                      true_mean^2)
    m <- .moment_test(trunc_samples, true_mean, true_sd)
    add("TEST_TRUNCATED_NORMAL", m$pass, m$mean, m$sd, true_mean, true_sd)
  }

  # ---- Write sample files -------------------------------------------------
  cat("[8/8] Writing sample files ...\n")
  files_ok <- TRUE
  if (!is.null(normal_samples)) {
    ok <- tryCatch({
      writeLines(sprintf("%.10f", normal_samples), "/app/normal_samples.txt")
      TRUE
    }, error = function(e) FALSE)
    files_ok <- files_ok && ok
    cat(sprintf("  /app/normal_samples.txt: %s\n", if (ok) "written" else "FAILED"))
  } else files_ok <- FALSE
  if (!is.null(exp_samples)) {
    ok <- tryCatch({
      writeLines(sprintf("%.10f", exp_samples), "/app/exponential_samples.txt")
      TRUE
    }, error = function(e) FALSE)
    files_ok <- files_ok && ok
    cat(sprintf("  /app/exponential_samples.txt: %s\n",
                if (ok) "written" else "FAILED"))
  } else files_ok <- FALSE
  add("TEST_SAMPLE_FILES", files_ok, detail =
        "normal_samples.txt and exponential_samples.txt written")

  # ---- Summary ------------------------------------------------------------
  df <- data.frame(test = names(results),
                   passed = unlist(results, use.names = FALSE),
                   row.names = NULL, stringsAsFactors = FALSE)
  cat("\n=== Summary ===\n")
  cat(sprintf("%d / %d tests passed\n", sum(df$passed), nrow(df)))
  if (!all(df$passed))
    cat("Failed tests:", paste(df$test[!df$passed], collapse = ", "), "\n")
  else
    cat("ALL TESTS PASSED\n")
  invisible(df)
}

